builds.command:
cat > /tmp/test_vulkan.cpp << 'EOF'
#include <iostream>
#include <ggml.h>
#include <ggml-backend.h>

int main() {
    std::cout << "Testing ggml backend detection..." << std::endl;

    // Load all backends
    ggml_backend_load_all();

    size_t dev_count = ggml_backend_dev_count();
    std::cout << "Found " << dev_count << " devices" << std::endl;

    for (size_t i = 0; i < dev_count; i++) {
        ggml_backend_dev_t dev = ggml_backend_dev_get(i);
        const char* name = ggml_backend_dev_name(dev);
        const char* desc = ggml_backend_dev_description(dev);
        enum ggml_backend_dev_type type = ggml_backend_dev_type(dev);

        std::cout << "Device " << i << ": " << name << std::endl;
        std::cout << "  Description: " << desc << std::endl;
        std::cout << "  Type: " << type;
        switch(type) {
            case GGML_BACKEND_DEVICE_TYPE_CPU: std::cout << " (CPU)"; break;
            case GGML_BACKEND_DEVICE_TYPE_GPU: std::cout << " (GPU)"; break;
            case GGML_BACKEND_DEVICE_TYPE_IGPU: std::cout << " (iGPU)"; break;
            case GGML_BACKEND_DEVICE_TYPE_ACCEL: std::cout << " (ACCEL)"; break;
            default: std::cout << " (unknown)"; break;
        }
        std::cout << std::endl;

        size_t free_mem, total_mem;
        ggml_backend_dev_memory(dev, &free_mem, &total_mem);
        std::cout << "  Memory: " << (free_mem / 1024 / 1024) << " MB free / " << (total_mem / 1024 / 1024) << " MB total" << std::endl;
    }

    return 0;
}
EOF

# Compile and run
g++ -o /tmp/test_vulkan /tmp/test_vulkan.cpp \
    -I./third_party/llama.cpp/ggml/include \
    -I./third_party/whisper.cpp/ggml/include \
    -I./third_party/ggml/include \
    -I./third_party/llama.cpp/include \
    -L./build/third_party/llama.cpp/ggml/src/ -L./build/third_party/whisper.cpp/ggml/src/ \
    -lggml -Wl,-rpath,./build/third_party/llama.cpp/ggml/src/ 2>&1
